{"code": "import math

def haversine(lat1, lon1, lat2, lon2, R=6371.0):
    p1, p2 = math.radians(lat1), math.radians(lat2)
    dphi = math.radians(lat2 - lat1)
    dlmb = math.radians(lon2 - lon1)
    a = math.sin(dphi/2)**2 + math.cos(p1)*math.cos(p2)*math.sin(dlmb/2)**2
    return 2*R*math.asin(math.sqrt(a))

# Nellore candidate coordinates
nellore_options = [(14.44306, 79.98611), (14.442599, 79.986458), (14.4465, 79.9873)]
# Dharmapuri town candidate coordinates
dharmapuri_options = [(12.1260, 78.1540), (12.106527, 78.136139), (12.12929, 78.16378), (12.1167, 78.15)]

for n in nellore_options:
    for d in dharmapuri_options:
        dist = haversine(n[0], n[1], d[0], d[1])
        print(f"Nellore {n} -> Dharmapuri {d}: {dist:.2f} km, rounded {round(dist)}")"}

